            'majors' => '[{"name":{"en":"Major in Engineering","km":"\\u1798\\u17bb\\u1781\\u1787\\u17c6\\u1793\\u17b6\\u1789\\u179c\\u17b7\\u179f\\u17d2\\u179c\\u1780\\u1798\\u17d2\\u1798\\u179f\\u17c6\\u178e\\u1784\\u17cb\\u179f\\u17ca\\u17b8\\u179c\\u17b7\\u179b"},"programs":{"bachelor":{"sections":[{"type":"richtext","title":{"en":"Career Opportunities","km":"\\u17b1\\u1780\\u17b6\\u179f\\u1780\\u17b6\\u179a\\u1784\\u17b6\\u179a"},"content":{"en":"<p>Upon successful completion of the Bachelor\'s Degree in Civil Engineering, graduates will be able to:<\\/p><p><strong>A. Technical Knowledge<\\/strong><\\/p><ol><li data-list=\\"bullet\\"><span class=\\"ql-ui\\" contenteditable=\\"false\\"><\\/span>PLO1: Explain and interpret scientific and mathematical principles related to civil engineering.<\\/li><li data-list=\\"bullet\\"><span class=\\"ql-ui\\" contenteditable=\\"false\\"><\\/span>PLO2: Study and analyze structural component designs.<\\/li><\\/ol><p><strong>B. Cognitive Skills<\\/strong><\\/p><ol><li data-list=\\"bullet\\"><span class=\\"ql-ui\\" contenteditable=\\"false\\"><\\/span>PLO3: Analyze geological data and evaluate the bearing capacity of foundations.<\\/li><li data-list=\\"bullet\\"><span class=\\"ql-ui\\" contenteditable=\\"false\\"><\\/span>PLO4: Evaluate project costs, develop plans, and solve engineering problems.<\\/li><li data-list=\\"bullet\\"><span class=\\"ql-ui\\" contenteditable=\\"false\\"><\\/span>PLO5: Conduct experiments and interpret experimental results.<\\/li><li data-list=\\"bullet\\"><span class=\\"ql-ui\\" contenteditable=\\"false\\"><\\/span>PLO6: Develop professional skills and engage in lifelong learning according to social contexts.<\\/li><\\/ol><p><strong>C. Interpersonal Skills and Responsibility<\\/strong><\\/p><ol><li data-list=\\"bullet\\"><span class=\\"ql-ui\\" contenteditable=\\"false\\"><\\/span>PLO7: Demonstrate teamwork skills and responsibility in professional duties.<\\/li><li data-list=\\"bullet\\"><span class=\\"ql-ui\\" contenteditable=\\"false\\"><\\/span>PLO8: Apply communication skills and follow ethical standards within communities and among technical professionals.<\\/li><\\/ol><p><strong>D. Numerical, Information Technology, and Communication Skills<\\/strong><\\/p><ol><li data-list=\\"bullet\\"><span class=\\"ql-ui\\" contenteditable=\\"false\\"><\\/span>PLO9: Develop numerical methods using computer programs for effective structural analysis.<\\/li><li data-list=\\"bullet\\"><span class=\\"ql-ui\\" contenteditable=\\"false\\"><\\/span>PLO10: Use construction material testing equipment and effectively provide training programs for others.<\\/li><\\/ol>","km":"<p>\\u1780\\u17d2\\u179a\\u17c4\\u1799\\u1796\\u17b8\\u1791\\u1791\\u17bd\\u179b\\u1794\\u17b6\\u1793\\u179f\\u1789\\u17d2\\u1789\\u17b6\\u1794\\u178f\\u17d2\\u179a\\u179c\\u17b7\\u179f\\u17d2\\u179c\\u1780\\u1798\\u17d2\\u1798\\u179f\\u17c6\\u178e\\u1784\\u17cb\\u179f\\u17ca\\u17b8\\u179c\\u17b7\\u179b \\u1793\\u17b7\\u179f\\u17d2\\u179f\\u17b7\\u178f\\u1793\\u17b9\\u1784\\u1791\\u1791\\u17bd\\u179b\\u1794\\u17b6\\u1793\\u17b1\\u1780\\u17b6\\u179f\\u1780\\u17b6\\u179a\\u1784\\u17b6\\u179a\\u178a\\u17bc\\u1785\\u1781\\u17b6\\u1784\\u1780\\u17d2\\u179a\\u17c4\\u1798\\u17d6<\\/p><ol><li data-list=\\"bullet\\"><span class=\\"ql-ui\\" contenteditable=\\"false\\"><\\/span>\\u179c\\u17b7\\u179f\\u17d2\\u179c\\u1780\\u179a\\u1782\\u17d2\\u179a\\u1794\\u17cb\\u1782\\u17d2\\u179a\\u1784\\u1782\\u1798\\u17d2\\u179a\\u17c4\\u1784\\u179c\\u17b7\\u179f\\u17d2\\u179c\\u1780\\u1798\\u17d2\\u1798: \\u179a\\u17c0\\u1794\\u1785\\u17c6\\u1795\\u17c2\\u1793\\u1780\\u17b6\\u179a \\u178a\\u17b9\\u1780\\u1793\\u17b6\\u17c6 \\u179a\\u17c0\\u1794\\u1785\\u17c6\\u1782\\u1798\\u17d2\\u179a\\u17c4\\u1784 \\u179a\\u17bd\\u1798\\u1791\\u17b6\\u17c6\\u1784\\u1780\\u17b6\\u179a\\u179a\\u17c0\\u1794\\u1785\\u17c6\\u179f\\u17c6\\u178e\\u17be \\u179a\\u1780\\u17d2\\u179f\\u17b6 \\u1780\\u17c6\\u178e\\u178f\\u17cb\\u178f\\u17d2\\u179a\\u17b6\\u